class HomeState extends State<Home>{List<I>items=[];List<String>cats=['عمومی'],tags=[];String cat='همه',status='همه',left='سطل زباله',right='امروز';bool multi=false;final chosen=<String>{};@override void initState(){super.initState();load();}bool today(DateTime d){final n=DateTime.now();return n.year==d.year&&n.month==d.month&&n.day==d.day;}Future<void>save()async{final p=await SharedPreferences.getInstance();await p.setString('items',jsonEncode(items.map((e)=>e.j()).toList()));await p.setStringList('cats',cats);await p.setStringList('tags',tags);await p.setString('cat',cat);await p.setString('status',status);await p.setString('left',left);await p.setString('right',right);}Future<void>load()async{final p=await SharedPreferences.getInstance();final raw=p.getString('items')??p.getString('arvin_items');if(raw!=null)items=(jsonDecode(raw)as List).map((e)=>I.from(Map<String,dynamic>.from(e))).toList();cats=p.getStringList('cats')??p.getStringList('arvin_categories')??['عمومی'];tags=p.getStringList('tags')??[];cat=p.getString('cat')??'همه';status=p.getString('status')??'همه';left=p.getString('left')??'سطل زباله';right=p.getString('right')??'امروز';for(final x in items){if(x.rem!=null)alarm(('i'+x.id).hashCode,'یادآوری آروین: ${x.title}',x.note,x.rem!);for(final f in x.fs){if(f.rem!=null)alarm(('f'+f.id).hashCode,'یادآوری پیگیری: ${x.title}',f.text.isEmpty?'زمان پیگیری فرا رسیده':f.text,f.rem!);}}setState((){});}List<I>get list{final n=DateTime.now();return items.where((x)=>!x.trash&& (status=='بایگانی'?x.arch:!x.arch)).where((x)=>cat=='همه'||x.cat==cat).where((x)=>status=='همه'||(status=='امروز'&&today(x.date))||(status=='آینده'&&x.date.isAfter(n))||(status=='عقب‌افتاده'&&x.date.isBefore(n)&&!today(x.date))||(status=='یادداشت‌ها'&&!x.task)||(status=='کارها'&&x.task)||(status=='بایگانی'&&x.arch)).toList();}
Future<void>edit({I?old,bool?task})async{final x=await showModalBottomSheet<I>(context:context,isScrollControlled:true,builder:(_)=>Editor(old:old,task:task??old?.task??false,cats:cats));if(x==null)return;if(old==null)items.add(x);else items[items.indexWhere((e)=>e.id==old.id)]=x;await save();if(x.rem!=null)alarm(('i'+x.id).hashCode,'یادآوری آروین: ${x.title}',x.note,x.rem!);setState((){});}
Future<void>follow(I x,{F?old})async{final f=await showDialog<F>(context:context,builder:(_)=>FD(old:old));if(f==null)return;if(old==null)x.fs.add(f);else x.fs[x.fs.indexOf(old)]=f;await save();if(f.rem!=null)alarm(('f'+f.id).hashCode,'یادآوری پیگیری: ${x.title}',f.text,f.rem!);setState((){});}
Future<void>backup()async{final d=await getApplicationDocumentsDirectory();final f=File('${d.path}/arvin_backup.json');await f.writeAsString(jsonEncode({'items':items.map((e)=>e.j()).toList(),'cats':cats,'tags':tags}));await Share.shareXFiles([XFile(f.path)],text:'پشتیبان آروین');}Future<void>restore()async{final r=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['json'],withData:true);if(r==null||r.files.single.bytes==null)return;final m=jsonDecode(utf8.decode(r.files.single.bytes!))as Map<String,dynamic>;items=(m['items']as List).map((e)=>I.from(Map<String,dynamic>.from(e))).toList();cats=List<String>.from(m['cats']??['عمومی']);tags=List<String>.from(m['tags']??[]);await save();setState((){});}
Future<void>pdf(I x)async{final d=pw.Document();d.addPage(pw.MultiPage(build:(_)=>[pw.Text(x.title),pw.Text('دسته: ${x.cat}'),pw.Text('تاریخ: ${jd(x.date)} ${tm(x.date)}'),pw.Text(x.note),...x.fs.map((f)=>pw.Text('${jd(f.at)} ${tm(f.at)} ${f.text}'))]));await Printing.sharePdf(bytes:await d.save(),filename:'arvin_${x.id}.pdf');}
Future<void>manage(String title,List<String>src,Future<void>Function(List<String>)done)async{final r=await showDialog<List<String>>(context:context,builder:(_)=>MD(title,src));if(r!=null){await done(r);setState((){});}}
Future<void>sw(I x,String a)async{if(a=='امروز')x.date=DateTime.now();if(a=='بایگانی')x.arch=true;if(a=='سطل زباله')x.trash=true;if(a=='پیگیری'&&x.task)await follow(x);if(a=='ویرایش')await edit(old:x);if(a=='اشتراک‌گذاری')await pdf(x);await save();setState((){});}
